// =====================================================================
// MODO DE OPERACAO — a unica coisa que muda na virada de amanha.
//   'observacao' = traduz e registra, mas NAO entrega ao CRM (risco zero)
//   'producao'   = entrega de verdade no fluxo do CRM
// =====================================================================
const MODO = 'observacao';

const WAHA_PUBLICO = 'https://n8n-waha.5k3mqv.easypanel.host';

const body = $input.first().json.body ?? $input.first().json;
const event = body.event;
const p = body.payload || {};
const info = p._data?.Info || {};

function parar(motivo, extra) {
  return [{ json: { modo: MODO, entregar: false, motivo, event, ...(extra || {}) } }];
}

// Acks e status ja sao tratados pelo fluxo "CRM - WAHA Ack Status".
if (event === 'message.ack' || event === 'session.status') {
  return parar('tratado_por_outro_fluxo');
}

// Reacoes, edicoes e apagadas: por enquanto seguem pela Evolution.
if (event !== 'message' && event !== 'message.any') {
  return parar('evento_nao_tratado');
}

// 'message.any' inclui o que o proprio CRM enviou (source='api'), que ja foi
// gravado no envio. So interessa aqui a mensagem escrita direto do celular da
// clinica — o mesmo caso que hoje a Evolution registra como 'phone_direct_synced'.
if (event === 'message.any' && !(p.fromMe === true && p.source !== 'api')) {
  return parar('duplicado_ou_enviado_pelo_crm');
}
if (event === 'message' && p.fromMe === true) {
  return parar('duplicado_message_any');
}

// ---------------------------------------------------------------------
// Telefone do paciente.
// ATENCAO: o campo 'from' do WAHA pode vir como LID anonimo
// (ex.: 253519185576031@lid). O telefone real fica em _data.Info.SenderAlt.
// Usar 'from' aqui quebraria a identificacao de todo paciente.
// ---------------------------------------------------------------------
const chatJid = info.Chat || p.from || null;
const altJid = info.SenderAlt || info.RecipientAlt || null;
const ehLid = String(chatJid || '').includes('@lid');
const jidTelefone = altJid || (ehLid ? null : chatJid);

// Hash estavel da mensagem (mesmo formato que a Evolution grava em external_id)
const idBruto = String(p.id || '');
const hash = info.ID || idBruto.split('_').pop();

if (!hash) return parar('sem_id_de_mensagem');

// Estrutura da mensagem: o WAHA ja entrega o mesmo formato interno que a
// Evolution usa (conversation / extendedTextMessage / imageMessage / ...).
const mensagem = p._data?.Message ? JSON.parse(JSON.stringify(p._data.Message)) : {};
if (!mensagem.conversation && !mensagem.extendedTextMessage && p.body && !p.hasMedia) {
  mensagem.conversation = p.body;
}

// Midia: o WAHA manda um LINK apontando para dentro do proprio container
// (http://localhost:3000/...). Reescrevemos para o endereco publico; o download
// e a conversao para base64 acontecem no proximo no.
let midiaUrl = null;
if (p.hasMedia && p.media?.url) {
  midiaUrl = String(p.media.url)
    .replace(/^https?:\/\/localhost:3000/i, WAHA_PUBLICO)
    .replace(/^https?:\/\/127\.0\.0\.1:3000/i, WAHA_PUBLICO);
}

// Payload no formato que o CRM ja sabe ler (mesmo desenho da Evolution).
const payloadCrm = {
  event: 'messages.upsert',
  instance: 'crmobesity',
  data: {
    key: {
      id: hash,
      remoteJid: jidTelefone || chatJid,
      remoteJidAlt: jidTelefone,
      participantAlt: jidTelefone,
      fromMe: p.fromMe === true,
      addressingMode: ehLid ? 'lid' : ''
    },
    pushName: info.PushName || p.notifyName || null,
    messageTimestamp: p.timestamp || Math.floor(Date.now() / 1000),
    message: mensagem
  }
};

return [{
  json: {
    modo: MODO,
    entregar: MODO === 'producao',
    motivo: 'ok',
    event,
    telefone_resolvido: !!jidTelefone,
    telefone: jidTelefone,
    era_lid: ehLid,
    hash,
    tem_midia: !!midiaUrl,
    midia_url: midiaUrl,
    midia_mimetype: p.media?.mimetype || null,
    midia_filename: p.media?.filename || null,
    texto: String(p.body || '').slice(0, 120),
    payload_crm: payloadCrm
  }
}];

// Baixa a midia do WAHA e converte para base64, que e o formato que o CRM
// espera hoje (a Evolution entrega assim). Sem esta etapa, foto de exame, PDF
// e audio chegariam vazios.
const item = $input.first().json;

if (!item.tem_midia || !item.midia_url) {
  return [{ json: { ...item, midia_ok: null } }];
}

const CHAVE_WAHA = 'COLE_AQUI_A_CHAVE_DO_WAHA';

try {
  const resp = await fetch(item.midia_url, { headers: { 'X-Api-Key': CHAVE_WAHA } });
  if (!resp.ok) {
    return [{ json: { ...item, midia_ok: false, midia_erro: `HTTP ${resp.status}` } }];
  }
  const buf = await resp.arrayBuffer();
  const bytes = new Uint8Array(buf);
  let bin = '';
  const CH = 8192;
  for (let i = 0; i < bytes.length; i += CH) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + CH));
  }
  const base64 = btoa(bin);

  // Injeta no mesmo lugar de onde o CRM ja le hoje.
  const payload = item.payload_crm;
  payload.data.message.base64 = base64;

  return [{ json: { ...item, payload_crm: payload, midia_ok: true, midia_bytes: bytes.length } }];
} catch (e) {
  return [{ json: { ...item, midia_ok: false, midia_erro: String(e).slice(0, 200) } }];
}
